CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamp NOT NULL, "updatedAt" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, "expiresAt" timestamp NOT NULL, token text UNIQUE NOT NULL, "createdAt" timestamp NOT NULL, "updatedAt" timestamp NOT NULL, "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON session("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamp, "refreshTokenExpiresAt" timestamp, scope text, password text, "createdAt" timestamp NOT NULL, "updatedAt" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamp NOT NULL, "createdAt" timestamp NOT NULL, "updatedAt" timestamp NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (owner_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, protocol jsonb NOT NULL, preferences jsonb NOT NULL, version integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS records (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, kind text NOT NULL, data jsonb NOT NULL, version integer NOT NULL, event_at timestamptz NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS records_feed_idx ON records(owner_id, event_at DESC, id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS records_occurrence_idx ON records(owner_id, (data->>'occurrenceId')) WHERE kind='administration' AND data->>'status' <> 'retracted' AND data->>'occurrenceId' IS NOT NULL;
CREATE TABLE IF NOT EXISTS revisions (id bigserial PRIMARY KEY, record_id text NOT NULL, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, version integer NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operations (owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, id text NOT NULL, hash text NOT NULL, result jsonb NOT NULL, PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS documents (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, name text NOT NULL, path text NOT NULL, bytes integer NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, subscription jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS reminder_jobs (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, occurrence_id text NOT NULL, due_at timestamptz NOT NULL, sent_at timestamptz, snoozed_until timestamptz);
CREATE TABLE IF NOT EXISTS import_keys (owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_id text NOT NULL, record_id text NOT NULL, imported_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,source_id));
